				if v != want(e) {
					return fmt.Errorf("%w: %s lane %d element %d holds (%d, %d), want (%d, %d)", errLayout,
						names[u], l, e, v/16, v%16, want(e)/16, want(e)%16)
				}
			}
		}
	}
